      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Tetrabenazine has very low absolute oral bioavailability (~5%) in patients, but its much lower molecular weight, lower TPSA, and rigid lipophilic structure limit transferability to the query.",
