    },
    {
      "card_ids": ["C30"],
      "claim": "Almorexant has low absolute oral bioavailability (~11%), but its much higher lipophilicity and poorer solubility profile limit transferability to the more polar query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High predicted: the most transferable human absolute-bioavailability evidence from basic, no-HBD, moderately polar molecules (donepezil ~100%, valbenazine ~49%, verapamil ~20-35%) supports F >= 20%; low-F tetrabenazine and almorexant are less aligned with the query's physicochemical profile.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query.",
